INSERT INTO AUDIT_TASK (
    ID, SOURCE_TYPE, SOURCE_ID, SOURCE_VERSION, REVIEW_TYPE, STATUS, CREATED_BY,
    REQUEST_ID, TRACE_ID, CREATED_AT, STARTED_AT, FINISHED_AT, VERSION_NO
) VALUES (
    #{id}, #{sourceType}, #{sourceId}, #{sourceVersion}, #{reviewType}, #{status}, #{createdBy},
    #{requestId}, #{traceId}, #{createdAt}, #{startedAt}, #{finishedAt}, #{versionNo}
)

mapper.select:
SELECT 
FROM (
    SELECT ,
           ROW_NUMBER() OVER (ORDER BY CREATED_AT DESC, ID DESC) AS PAGE_ROW_NO
    FROM (
        SELECT ,
               ROW_NUMBER() OVER (
                   PARTITION BY SOURCE_ID ORDER BY CREATED_AT DESC, ID DESC
               ) AS SOURCE_ROW_NO
        FROM AUDIT_TASK
        WHERE SOURCE_TYPE = #{sourceType} AND REVIEW_TYPE = #{reviewType}
    ) LATEST_BY_SOURCE
    WHERE SOURCE_ROW_NO = 1
) PAGE_ROWS
WHERE PAGE_ROW_NO > #{offset} AND PAGE_ROW_NO <= #{endRow}
ORDER BY CREATED_AT DESC, ID DESC

SELECT COUNT(DISTINCT SOURCE_ID)
FROM AUDIT_TASK
WHERE SOURCE_TYPE = #{sourceType} AND REVIEW_TYPE = #{reviewType}

SELECT 
FROM (
    SELECT ,
           ROW_NUMBER() OVER (ORDER BY CREATED_AT DESC, ID DESC) AS PAGE_ROW_NO
    FROM AUDIT_TASK
    WHERE SOURCE_TYPE = #{sourceType} AND REVIEW_TYPE = #{reviewType}
) PAGE_ROWS
WHERE PAGE_ROW_NO > #{offset} AND PAGE_ROW_NO <= #{endRow}
ORDER BY CREATED_AT DESC, ID DESC

